p=Path('devel/fuzz/gnutls_pkcs12_key_parser.in/key-cert-crl.p12')
b=bytearray(p.read_bytes())
# dump offsets for pattern around second encrypted CRL bag
patterns=[bytes.fromhex('3082027B06092A864886F70D010706'), bytes.fromhex('80820200'), bytes.fromhex('308205A106092A864886F70D010701')]
for pat in patterns:
    print(pat.hex(), b.find(pat))
# all encrypted content explicit 80 82 04.. or 02
for i in range(len(b)-4):
    if b[i]==0x80 and b[i+1]==0x82:
        print('ctx0 octet?', i, b[i:i+8].hex())
